<span class="line"><span style="color:#ABB2BF;">        weights </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> weights </span><span style="color:#56B6C2;">/</span><span style="color:#ABB2BF;"> weights.</span><span style="color:#61AFEF;">sum</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;font-style:italic;">axis</span><span style="color:#56B6C2;">=-</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">keepdims</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">True</span><span style="color:#ABB2BF;">)</span></span>
